/* Phase 3: original, original-edition Netzwerk A1.1 visual situation lessons. Not copied from textbook pages or artwork. Teacher validation required. */
(()=>{
'use strict';
const data={"a11-greetings":{"chapter":1,"title":"Greeting choices","tiles":[["Classmate","du","informal"],["Teacher","Sie","polite"],["Farewell","Auf Wiedersehen","polite"]],"scenes":[{"name":"Meeting a classmate","context":"A new learner sits beside you. Greet them and ask their name without using an overly formal expression.","model":"Hallo! Ich heiße Sara. Wie heißt du?","translation":"Hello! My name is Sara. What is your name?","insight":"Use du with a classmate; the matching verb is heißt. A greeting followed by a short question starts the conversation naturally.","question":"Which question fits a classmate?","options":["Wie heißen Sie?","Wie heißt du?","Was kostet das?"],"correct":1,"why":"Wie heißt du? is the informal name question."},{"name":"Meeting a teacher","context":"You enter the school office and speak to an unfamiliar teacher. Use the polite form consistently.","model":"Guten Tag. Ich bin Leon. Wie heißen Sie?","translation":"Good day. I am Leon. What is your name?","insight":"Formal Sie takes the conjugated verb heißen and starts with a capital letter. Avoid mixing du and Sie in the same formal exchange.","question":"Which question is polite?","options":["Wie heißen Sie?","Wie heißt du?","Was machst du?"],"correct":0,"why":"Wie heißen Sie? correctly pairs Sie with heißen."},{"name":"Saying goodbye","context":"The conversation at the school office has ended. Choose a farewell suitable for the person and setting.","model":"Vielen Dank. Auf Wiedersehen!","translation":"Thank you very much. Goodbye!","insight":"Auf Wiedersehen is a reliable polite farewell. Tschüss suits friends; Gute Nacht is usually said before going to sleep.","question":"Choose a polite farewell.","options":["Gute Nacht!","Hallo!","Auf Wiedersehen!"],"correct":2,"why":"Auf Wiedersehen is a polite farewell."}]},"a11-origin-spelling":{"chapter":1,"title":"Names and places","tiles":[["Vorname","Lea","first name"],["Land","Indien","country"],["Buchstaben","L · E · A","spelling"]],"scenes":[{"name":"Origin versus home","context":"Someone asks where you come from and where you currently live. These are two different questions.","model":"Ich komme aus Indien. Ich wohne in Berlin.","translation":"I come from India. I live in Berlin.","insight":"Woher? is about origin and often uses komme aus. Wo? asks for location and can be answered with wohne in.","question":"Which asks about origin?","options":["Woher kommst du?","Wo wohnst du?","Wie heißt du?"],"correct":0,"why":"Woher means from where."},{"name":"Spell your name","context":"At reception your name is hard to hear. Repeat it and offer the letters one by one.","model":"Mein Name ist Lea: L – E – A.","translation":"My name is Lea: L – E – A.","insight":"Wie schreibt man das? is useful for asking how something is spelled. The letters should be spoken separately.","question":"Which asks for a spelling?","options":["Wo ist das?","Wie schreibt man das?","Was kostet das?"],"correct":1,"why":"Wie schreibt man das? asks how it is written."},{"name":"Languages you speak","context":"You meet learners with different languages. Give a short, truthful answer about your German.","model":"Ich spreche Englisch und ein bisschen Deutsch.","translation":"I speak English and a little German.","insight":"Use sprechen for languages. The ich form is spreche and the du form is sprichst. Ein bisschen means a little.","question":"Complete: Ich ___ Deutsch.","options":["sprichst","sprechen","spreche"],"correct":2,"why":"The ich form is spreche."}]},"a11-hobbies":{"chapter":2,"title":"Interests and plans","tiles":[["Montag","Musik","busy"],["Donnerstag","frei","available"],["Freitag","Kino","plan"]],"scenes":[{"name":"Describe a hobby","context":"Two classmates are comparing interests. Say which activity you enjoy instead of only naming the activity.","model":"Ich lese gern. Und du?","translation":"I like reading. And you?","insight":"Verb plus gern expresses enjoyment: Ich lese gern. Gut describes doing something well; it does not mean the same as gern.","question":"Which expresses enjoyment?","options":["Ich spiele gern Tennis.","Ich bin Tennis.","Ich habe Tennis gut."],"correct":0,"why":"Gern after the verb expresses enjoyment."},{"name":"Ask about a day","context":"You want to see a film on Friday. Check whether your classmate can join you.","model":"Hast du am Freitag Zeit?","translation":"Do you have time on Friday?","insight":"Use am before weekdays: am Freitag, am Montag. Hast du … Zeit? is a practical invitation question.","question":"Which asks about Friday?","options":["Wo ist Freitag?","Hast du am Freitag Zeit?","Wie heißt Freitag?"],"correct":1,"why":"Am Freitag means on Friday."},{"name":"Offer another day","context":"Your friend is unavailable today but free tomorrow. Keep the plan alive by suggesting a different time.","model":"Heute habe ich keine Zeit. Morgen geht es.","translation":"I have no time today. Tomorrow works.","insight":"Heute and morgen can start a sentence. The conjugated verb still follows in second position: Morgen geht es.","question":"Which says tomorrow works?","options":["Ich bin morgen nicht.","Heute ist Dienstag.","Morgen geht es."],"correct":2,"why":"Morgen geht es means tomorrow works."}]},"a11-jobs-seasons":{"chapter":2,"title":"Work and seasons","tiles":[["Name","Jonas","person"],["Beruf","Koch","job"],["Arbeitszeit","10–18 Uhr","hours"]],"scenes":[{"name":"Read a job profile","context":"A short profile lists someone's occupation and workplace. Tell the two facts apart.","model":"Jonas ist Koch. Er arbeitet im Restaurant.","translation":"Jonas is a cook. He works in a restaurant.","insight":"A profession after sein is commonly used without an indefinite article: Er ist Koch. Use arbeitet to describe the workplace.","question":"Which describes a profession?","options":["Er ist Koch.","Er hat Koch.","Er sein Koch."],"correct":0,"why":"Er ist Koch is a natural occupation statement."},{"name":"Understand work hours","context":"The job profile shows the person's shift. Describe the hours using an interval expression.","model":"Ich arbeite von zehn bis achtzehn Uhr.","translation":"I work from ten until eighteen o’clock.","insight":"Von … bis … means from … until … and works with opening hours, shifts and travel times.","question":"Which gives an interval?","options":["am zehn nach achtzehn","von zehn bis achtzehn Uhr","bei zehn achtzehn"],"correct":1,"why":"Von … bis … gives a time range."},{"name":"Choose a season","context":"You describe an activity you like in summer. The time expression starts your sentence.","model":"Im Sommer fahre ich gern Rad.","translation":"In summer I like cycling.","insight":"Im Sommer and im Winter name seasons. When the time phrase begins the sentence, the verb comes next.","question":"Choose correct word order.","options":["Im Sommer ich fahre Rad.","Sommer ich Rad fahre.","Im Sommer fahre ich Rad."],"correct":2,"why":"Fahre follows the opening time phrase."}]},"a11-city-places":{"chapter":3,"title":"Places in town","tiles":[["der Bahnhof","station","masculine"],["das Museum","museum","neuter"],["die Bank","bank","feminine"]],"scenes":[{"name":"Read the labels","context":"A visitor studies a town map with public buildings. Say the names with their correct articles.","model":"Das Museum ist in der Stadt.","translation":"The museum is in the city.","insight":"Learn nouns and articles together: der Bahnhof, das Museum, die Bank. The article is an important part of the German word.","question":"Which article goes with Museum?","options":["die Museum","das Museum","der Museum"],"correct":1,"why":"Museum is neuter: das Museum."},{"name":"What is nearby?","context":"A visitor asks if there is a station near the square. State that it exists.","model":"Hier gibt es einen Bahnhof.","translation":"There is a train station here.","insight":"Es gibt takes an accusative object. The masculine article ein becomes einen before Bahnhof.","question":"Complete: Hier gibt es ___ Bahnhof.","options":["einen","ein","eine"],"correct":0,"why":"The masculine object requires einen."},{"name":"What is not here?","context":"Your map shows no bank. Explain this without implying that the entire town has no buildings.","model":"Hier gibt es keine Bank.","translation":"There is no bank here.","insight":"Use keine before feminine Bank to negate the noun. Nicht is not the normal way to negate this noun phrase.","question":"Which means no bank here?","options":["Hier gibt es nicht Bank.","Hier gibt es keinen Bank.","Hier gibt es keine Bank."],"correct":2,"why":"Keine negates the feminine noun Bank."}]},"a11-city-directions":{"chapter":3,"title":"Finding your way","tiles":[["Start","Bahnhof","station"],["Weg","geradeaus","straight"],["Ziel","Museum","destination"]],"scenes":[{"name":"Ask for directions","context":"You have reached the train station but cannot find the museum. Get someone's attention politely.","model":"Entschuldigung, wo ist das Museum?","translation":"Excuse me, where is the museum?","insight":"Entschuldigung is a polite opening. Wo ist …? asks for the location of a particular place.","question":"Which asks where the museum is?","options":["Wo ist das Museum?","Wie heißt das Museum?","Was kostet das Museum?"],"correct":0,"why":"Wo ist …? is a location question."},{"name":"Follow the route","context":"A passer-by tells you to go straight, then turn right. Identify the direction words.","model":"Gehen Sie geradeaus und dann rechts.","translation":"Go straight ahead and then right.","insight":"Geradeaus means straight, rechts means right, and links means left. Gehen Sie is a polite imperative.","question":"Which means right?","options":["links","rechts","geradeaus"],"correct":1,"why":"Rechts means right."},{"name":"Travel by bus","context":"Your destination is too far to walk. Ask whether the bus goes there.","model":"Fährt der Bus zum Museum?","translation":"Does the bus go to the museum?","insight":"A yes/no question often puts the conjugated verb first. Zum combines zu and dem.","question":"Which asks about the bus?","options":["Wo Bus Museum?","Der Bus ist Museum?","Fährt der Bus zum Museum?"],"correct":2,"why":"Fährt starts the yes/no question."}]},"a11-food-shops":{"chapter":4,"title":"Meals and shopping","tiles":[["Frühstück","morning","breakfast"],["Mittagessen","midday","lunch"],["Abendessen","evening","dinner"]],"scenes":[{"name":"Name the meal","context":"A weekly plan shows food for the morning, midday and evening. Identify the midday meal.","model":"Zum Mittagessen gibt es Brot und Käse.","translation":"For lunch there is bread and cheese.","insight":"Frühstück is breakfast, Mittagessen is lunch and Abendessen is the evening meal. Keep the articles with food nouns.","question":"Which means lunch?","options":["das Mittagessen","das Frühstück","das Abendessen"],"correct":0,"why":"Mittagessen names the midday meal."},{"name":"Check the cupboard","context":"Before shopping, work out what the household already has and what it needs.","model":"Haben wir Tomaten? Nein, wir brauchen Tomaten.","translation":"Do we have tomatoes? No, we need tomatoes.","insight":"Haben wir …? checks availability. Wir brauchen … states a need. Together they support a real shopping conversation.","question":"Which means we need tomatoes?","options":["Wir heißen Tomaten.","Wir brauchen Tomaten.","Wir wohnen Tomaten."],"correct":1,"why":"Brauchen means need."},{"name":"Choose a shop","context":"You want fresh bread rolls for the morning. Match the food to the right kind of shop.","model":"Ich kaufe Brötchen in der Bäckerei.","translation":"I buy rolls at the bakery.","insight":"A Bäckerei sells bread and rolls. Use in der Bäckerei when describing where the purchase happens.","question":"Where can you buy Brötchen?","options":["in der Bank","im Museum","in der Bäckerei"],"correct":2,"why":"Brötchen are usually bought at a bakery."}]},"a11-accusative-restaurant":{"chapter":4,"title":"In the shop","tiles":[["der Apfel","apple","noun"],["einen Apfel","an apple","object"],["zwei Äpfel","two apples","quantity"]],"scenes":[{"name":"Choose an object","context":"You add an apple to your basket. Say what you are buying and notice the article.","model":"Ich kaufe einen Apfel.","translation":"I am buying an apple.","insight":"Masculine ein becomes einen when the noun is a direct object. This is the accusative. Feminine eine and neuter ein stay unchanged in this pattern.","question":"Complete: Ich kaufe ___ Apfel.","options":["ein","eine","einen"],"correct":2,"why":"Apfel is masculine, so use einen."},{"name":"Make a request","context":"A café worker asks what you would like. Ask politely for tea.","model":"Ich möchte einen Tee, bitte.","translation":"I would like a tea, please.","insight":"Ich möchte … is useful for polite requests. Tee is masculine and takes einen here as the object.","question":"Which request is correct?","options":["Ich möchte einen Tee, bitte.","Ich möchte eine Tee, bitte.","Ich möchte ein Tee, bitte."],"correct":0,"why":"Einen is the accusative article for Tee."},{"name":"Ask the price","context":"You are buying a kilogram of apples. Ask the assistant the cost.","model":"Was kostet ein Kilo Äpfel?","translation":"How much does a kilogram of apples cost?","insight":"Was kostet …? asks about the price of one item or quantity. Ein Kilo is a precise quantity phrase.","question":"Which asks about a price?","options":["Woher kommen die Äpfel?","Was kostet ein Kilo Äpfel?","Wie heißen die Äpfel?"],"correct":1,"why":"Was kostet …? asks the price."}]},"a11-daily-time":{"chapter":5,"title":"Clocks and routine","tiles":[["07:30","halb acht","time"],["08:00","acht Uhr","time"],["18:15","Viertel nach sechs","time"]],"scenes":[{"name":"Half past the hour","context":"The clock reads 07:30. German calls this time by looking forward to the next hour.","model":"Es ist halb acht.","translation":"It is half past seven.","insight":"Halb acht means halfway to eight, so the clock reads 07:30, not 08:30. Compare the spoken expression with the hour hand.","question":"What is halb acht?","options":["08:30","07:30","07:15"],"correct":1,"why":"Halb acht means 07:30."},{"name":"Describe a routine","context":"You leave for work at eight. Explain the time and the activity in a single sentence.","model":"Um acht Uhr fahre ich zur Arbeit.","translation":"At eight o’clock I travel to work.","insight":"Um introduces an exact time. With a time expression first, the conjugated verb follows: Um acht Uhr fahre ich …","question":"Which has correct word order?","options":["Um acht Uhr fahre ich zur Arbeit.","Um acht Uhr ich fahre zur Arbeit.","Ich um acht Uhr fahre zur Arbeit."],"correct":0,"why":"Fahre follows the time phrase."},{"name":"Express a need","context":"You have homework to finish. Explain the necessity using a modal verb.","model":"Ich muss heute lernen.","translation":"I have to study today.","insight":"After a modal verb such as muss, the second verb appears at the end in the infinitive form.","question":"Complete: Ich muss heute ___.","options":["lerne","lernst","lernen"],"correct":2,"why":"After muss use the infinitive lernen."}]},"a11-family-appointments":{"chapter":5,"title":"Family and appointments","tiles":[["Familie","meine Schwester","relative"],["Mittwoch","15 Uhr","meeting"],["Antwort","Leider nicht","reply"]],"scenes":[{"name":"Introduce family","context":"Your classmate asks about a member of your family. Use a possessive form with the correct gender.","model":"Das ist meine Schwester.","translation":"This is my sister.","insight":"Schwester is feminine, so use meine in this simple expression. Mein and meine must agree with the noun.","question":"Complete: Das ist ___ Schwester.","options":["mein","meine","meinen"],"correct":1,"why":"Use meine with Schwester."},{"name":"Arrange a meeting","context":"You propose Wednesday at three in the afternoon. Combine day and time correctly.","model":"Hast du am Mittwoch um fünfzehn Uhr Zeit?","translation":"Do you have time on Wednesday at 3 p.m.?","insight":"Use am with a weekday and um with a clock time. In the question Hast du …?, the conjugated verb comes first.","question":"Which gives Wednesday at 3 p.m.?","options":["am Mittwoch um fünfzehn Uhr","um Mittwoch am fünfzehn Uhr","in Mittwoch für fünfzehn Uhr"],"correct":0,"why":"Am is for weekdays, um for clock time."},{"name":"Say no politely","context":"You cannot make the suggested meeting. Decline and leave room for another plan.","model":"Leider kann ich am Mittwoch nicht. Geht Donnerstag?","translation":"Unfortunately I cannot on Wednesday. Does Thursday work?","insight":"Leider softens a refusal. Kann expresses ability or availability; another day can follow as an alternative.","question":"Which is a polite refusal?","options":["Ja, um acht Uhr.","Wie heißt du?","Leider kann ich nicht."],"correct":2,"why":"Leider kann ich nicht is a polite refusal."}]},"a11-birthdays-invitations":{"chapter":6,"title":"Dates and invitations","tiles":[["Anlass","Geburtstag","birthday"],["Wann","12. Mai · 18 Uhr","date"],["Ort","bei mir","place"]],"scenes":[{"name":"Say a date","context":"Your birthday invitation needs a date. Read it as a German calendar expression.","model":"Ich habe am zwölften Mai Geburtstag.","translation":"My birthday is on the twelfth of May.","insight":"Use am with calendar dates and an ordinal form such as am zwölften Mai. A specific time is introduced by um.","question":"Which goes with a date?","options":["am","um","aus"],"correct":0,"why":"Calendar dates commonly use am."},{"name":"Invite a friend","context":"You plan a party on Saturday. Ask a friend whether they will come.","model":"Kommst du am Samstag zu meiner Party?","translation":"Are you coming to my party on Saturday?","insight":"In a yes/no question the conjugated verb starts the sentence: Kommst du …? Ja, gern! accepts the invitation.","question":"Which is an invitation?","options":["Was kostet die Party?","Kommst du am Samstag zu meiner Party?","Woher kommst du?"],"correct":1,"why":"Kommst du …? is an invitation question."},{"name":"Use anrufen","context":"You are going to phone a friend tomorrow. Say this in a present-tense sentence.","model":"Ich rufe dich morgen an.","translation":"I will call you tomorrow.","insight":"Anrufen is separable. Rufe is near the start of the main clause and an goes at the end.","question":"Complete: Ich rufe dich morgen ___.","options":["auf","mit","an"],"correct":2,"why":"Anrufen separates to rufe … an."}]},"a11-restaurant-past":{"chapter":6,"title":"Meal and memory","tiles":[["Speisekarte","menu","choose"],["Rechnung","bill","pay"],["Gestern","war · hatte","past"]],"scenes":[{"name":"Request the bill","context":"You have finished your meal and want to pay. Make a short polite request.","model":"Die Rechnung, bitte.","translation":"The bill, please.","insight":"Die Rechnung is the bill. Bitte makes the request polite. The Speisekarte is the menu, which is not what you need now.","question":"Which asks for the bill?","options":["Die Rechnung, bitte.","Der Bahnhof, bitte.","Das Wörterbuch, bitte."],"correct":0,"why":"Die Rechnung, bitte is a polite bill request."},{"name":"Describe the meal","context":"You tell a friend about yesterday's dinner. Use the past form of sein.","model":"Das Essen war sehr gut.","translation":"The food was very good.","insight":"War is a past form of sein. Contrast Das Essen ist gut (now) and Das Essen war gut (then).","question":"Which describes the past?","options":["Das Essen ist gut.","Das Essen war sehr gut.","Das Essen sind gut."],"correct":1,"why":"War is a past form of sein."},{"name":"Say what you had","context":"Someone asks about yesterday's meal. Answer using the past form of haben.","model":"Ich hatte gestern eine Suppe.","translation":"I had a soup yesterday.","insight":"Hatte is the ich simple-past form of haben. Gestern signals yesterday.","question":"Complete: Ich ___ gestern eine Suppe.","options":["habe","bin","hatte"],"correct":2,"why":"Hatte expresses past possession or experience."}]}};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function stats(id,all){const d=data[id],p=all?.[id]||{};return {total:d?.scenes.length||0,answered:d?.scenes.filter((_,i)=>!!p[i]).length||0,correct:d?.scenes.filter((_,i)=>p[i]?.correct).length||0};}
function render(id,all,choices){
const d=data[id];if(!d)return '';
const done=all?.[id]||{},counts=stats(id,all);
const visual='<div class="p3-visual"><div class="p3-visual-label">Everyday German · Visual language board</div><div class="p3-tiles">'+d.tiles.map(([a,b,c],i)=>'<div class="p3-tile"><span>'+esc(a)+'</span><strong>'+esc(b)+'</strong><small>'+esc(c)+'</small></div>').join('<span class="p3-arrow" aria-hidden="true">→</span>')+'</div><p>Use this visual to understand the situation, then try the three short scenes.</p></div>';
return '<section class="p3-lab" aria-label="Visual situation practice"><header class="p3-lab-header"><div><span class="eyebrow">Three original scenes · Chapter '+d.chapter+'</span><h3>See it. Understand it. Say it.</h3><p>Read a practical scene, study the German and test your understanding. Open any scene to practise.</p></div><div class="p3-score">'+counts.correct+'/3 <small>correct · '+counts.answered+' tried</small></div></header>'+visual+'<div class="p3-scenes">'+d.scenes.map((s,i)=>{
 const a=done[i],selected=choices?.[id+':'+i];
 return '<details class="p3-scene" '+(i===0?'open':'')+'><summary><span class="p3-scene-no">'+(i+1)+'</span><strong>'+esc(s.name)+'</strong><span class="p3-scene-status">'+(a?(a.correct?'✓ Correct':'↻ Review'):'Practise')+'</span></summary><div class="p3-scene-body"><p>'+esc(s.context)+'</p><div class="p3-example"><div><strong lang="de">'+esc(s.model)+'</strong><span>'+esc(s.translation)+'</span></div><button type="button" class="view-link" data-speak="'+esc(s.model)+'" aria-label="Listen to German example">♫ Listen</button></div><p class="p3-rule"><b>Understand:</b> '+esc(s.insight)+'</p><h4>'+esc(s.question)+'</h4><div class="p3-options" role="group" aria-label="'+esc(s.question)+'">'+s.options.map((o,j)=>'<button type="button" class="p3-option '+(selected===j?'selected ':'')+(a&&j===s.correct?'correct ':'')+(a&&j===a.chosen&&!a.correct?'incorrect':'')+'" data-phase3-choice="'+id+'|'+i+'|'+j+'" aria-pressed="'+(selected===j)+'" '+(a?'disabled':'')+'>'+esc(o)+'</button>').join('')+'</div>'+(a?'<div class="p3-feedback '+(a.correct?'':'p3-review')+'" role="status"><b>'+(a.correct?'Correct.':'Review this point.')+'</b> '+esc(s.why)+' <button type="button" class="view-link" data-phase3-retry="'+id+'|'+i+'">Try again</button></div>':'<button type="button" class="btn btn-primary btn-small" data-phase3-check="'+id+'|'+i+'" '+(!Number.isInteger(selected)?'disabled':'')+'>Check answer</button>')+'</div></details>';
}).join('')+'</div><p class="p3-foot">Independent AmberTheory learning material · Not reproduced textbook exercises · Language review pending</p></section>';
}
window.GERMAN_PHASE3={data,stats,render};
})();